import os
import logging
import time
import datetime
from moler.util.moler_test import MolerTest
from moler.device import DeviceFactory
from moler.exceptions import ConnectionObserverTimeout
from taf.rfrl.bts.devices.generic_bts import GenericBts, login_logout
from taf.rfrl.utilities.tl_config import load_moler_configuration_from_tl
from taf.rfrl.bts.devices.du.cell_operations import GnbCellOperations
from taf.rfrl.bts.devices.du.logs_collecting.btslog_collector import GnbBtslogCollector


class MeasureSoftwareActivation(GenericBts):
    """Base keywords for eNB and gNB"""

    def __init__(self, bts_type='GNB'):
        """
        Constructor of GenericBbbu class.
        :param bts_type: GNB|ENB
        :return: None
        """
        super(MeasureSoftwareActivation, self).__init__(bts_type=bts_type)
        self.cell = GnbCellOperations()
        self.log = GnbBtslogCollector()

    def measure_du_software_activation_time(self, path, success_rate, average_target, timeout=900, bts_id=0, du_id=0):
        """
        Perform DU sw activation, measure time and verify if meet average time target and success rate ratio.
        :param path: list of absolute paths on VM with expected DU build to download
        :param bts_id:  default BTS id
        :param du_id: default DU id
        :param success_rate: Target PASSED to RUNS ratio
        :param average_target: Target sw download time in seconds.
        :param timeout:  time in seconds to wait for sw activation
        """
        max_target = 1.2 * float(average_target)
        passed = 0
        failed = 0
        runs = len(path)
        passed_time_results = []

        for p in path:
            activation_time_result = self._measure_du_software_activation_time(p, timeout=int(timeout), bts_id=0,
                                                                               du_id=0)
            time.sleep(120)

            if activation_time_result == "FileNotFoundError":
                runs -= 1
                logging.warning("FileNotFoundError for {}. Skipping...".format(p))
            elif isinstance(activation_time_result, datetime.timedelta):
                if max_target < activation_time_result.total_seconds():
                    failed += 1
                else:
                    passed += 1
                    passed_time_results.append(activation_time_result.total_seconds())
            else:
                failed += 1

        exceptions = []
        if len(passed_time_results) > 0:
            average_sw_activation_time = sum(passed_time_results) / len(passed_time_results)
            logging.info("Average SW activation duration {}".format(average_sw_activation_time))

            if int(average_target) <= int(average_sw_activation_time):
                exceptions.append(AverageSwActivationDurationNotMet("Average Sw activation time {}s exceed presume "
                                                                    "value {}s".format(average_sw_activation_time,
                                                                                       average_target)))

        if runs > 0:
            passed_ratio = passed / runs
            if float(passed_ratio) < float(success_rate):
                exceptions.append(SwActivationDurationNotMet("Runs: {}, Failed: {}, Ratio: {} Target "
                                                             "not met".format(runs, failed, passed_ratio)))

        if exceptions:
            raise SwActivationDurationNotMet("\n".join([repr(e) for e in exceptions]))
        elif runs == 0 or len(passed_time_results) == 0:
            raise SwActivationDurationNotMet("No software activation was performed or no test passed. Runs: {}, "
                                             "Passed activations: {}".format(runs, len(passed_time_results)))
        else:
            logging.info("Runs: {}, Ratio: {}, Avg time: {} "
                         "Max time: {}".format(runs, passed_ratio, round(average_sw_activation_time, 2),
                                               max(passed_time_results)))

    @load_moler_configuration_from_tl()
    @MolerTest.raise_background_exceptions(check_steps_end=True)
    @login_logout
    def _measure_du_software_activation_time(self, path, timeout=1200, bts_id=0, du_id=0):
        """
        Perform DU sw activation, measure time and verify if meet average time target and success rate ratio.
        :param path: list of absolute paths on VM with expected DU build to update
        :param bts_id:  default BTS id
        :param du_id: default DU id
        :param timeout:  time in seconds to wait for sw activation
        """
        if not os.path.exists(path):
            MolerTest.steps_end()
            return "FileNotFoundError"

        try:
            MolerTest.info("Prepare build to activation - downloading... {}".format(datetime.datetime.now()))
            self.admin.update_software(sw_package=path, should_activate=False, timeout=timeout,
                                       connection=self.rest_alias.format(bts_id, du_id))
            MolerTest.info("Download build Finish {}".format(datetime.datetime.now()))

            cell_ids = self.cell._get_all_global_cell_ids(bts_id=bts_id, du_id=du_id)
            MolerTest.info(cell_ids)

            syslog = DeviceFactory.get_device(self.syslog_alias.format(bts_id, du_id))
            syslog.goto_state('SYSLOG', keep_state=False)
            first_cell_down = syslog.get_event(event_name="cell_status_from_online_to_offline",
                                               event_params={"till_occurs_times": 1})
            first_cell_down.start()

            MolerTest.info("Start sw_activation {}".format(datetime.datetime.now()))
            self.admin.update_software(sw_package=path, should_activate=True, timeout=timeout,
                                       connection=self.rest_alias.format(bts_id, du_id))

            first_cell_down_result = first_cell_down.await_done(timeout=200)
            MolerTest.info("First_CELL_down_RESULT" + "".join(map(str, first_cell_down_result)))

            syslog.goto_state('SYSLOG', keep_state=False)
            last_cell_up = syslog.get_event(event_name="cell_status_from_offline_to_online",
                                            event_params={"till_occurs_times": len(cell_ids)})
            last_cell_up_result = last_cell_up(timeout=int(timeout))

            self.log.stop_collecting_syslog()
            MolerTest.info("Sw activation finish: {}".format(datetime.datetime.now()))
            MolerTest.info("LAST_CELL_UP_RESULT" + "".join(map(str, last_cell_up_result)))

            start_activation_time = first_cell_down_result[0]['time']
            end_activation_time = last_cell_up_result[len(cell_ids) - 1]['time']
            MolerTest.steps_end()

        except ConnectionObserverTimeout as e:
            logging.warning("ConnectionObserverTimeout: {}".format(e))
            MolerTest.steps_end()
            return

        MolerTest.info("Start time: " + str(start_activation_time) + "   type: " + str(type(start_activation_time)))
        MolerTest.info("End time: " + str(end_activation_time) + "   type: " + str(type(end_activation_time)))
        sw_activation_time = (end_activation_time - start_activation_time)
        MolerTest.info("Duration of Software {} activation: {}".format(path, sw_activation_time.total_seconds()))
        return sw_activation_time


class SwActivationDurationNotMet(Exception):
    pass


class AverageSwActivationDurationNotMet(SwActivationDurationNotMet):
    pass
